package lesson_2;

public class CompareNumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		compareNumbers();
	}

	public static void compareNumbers () {
		int a = 0;
		int b = 2;
		if (a >= b) {
			System.out.println("a>=b");
		}
		else {
			System.out.println("a<b");
	    }
	}
	
}
